314	public final class Reservation {
315	
316	    private final long id;
317	    private final int roomNumber;
318	    private final Guest guest;
319	    private final LocalDate checkIn;
320	    private final LocalDate checkOut;
321	    private final int guests;
322	    private final RatePlan ratePlan;
323	    private final Price price;
324	    private ReservationStatus status;
325	    private BigDecimal amountPaid;
