327	
328	    Reservation(long id, NewReservation request, Price price) {
329	        this(id, request, price, ReservationStatus.PENDING, PriceCalculator.cents(BigDecimal.ZERO), null);
330	    }
331	
332	    Reservation(
333	            long id,
334	            NewReservation request,
335	            Price price,
336	            ReservationStatus status,
337	            BigDecimal amountPaid,
338	            BigDecimal refund) {
339	        this.id = id;
340	        this.roomNumber = request.roomNumber();
341	        this.guest = request.guest();
342	        this.checkIn = request.checkIn();
343	        this.checkOut = request.checkOut();
344	        this.guests = request.guests();
345	        this.ratePlan = request.ratePlan();
346	        this.price = price;
347	        this.status = status;
348	        this.amountPaid = amountPaid;
349	        this.refund = refund;
350	    }
351	
352	    public long id() {
353	        return id;
354	    }
355	
356	    public int roomNumber() {
357	        return roomNumber;
358	    }
359	
360	    public Guest guest() {
361	        return guest;
362	    }
363	
364	    public LocalDate checkIn() {
365	        return checkIn;
366	    }
367	
368	    public LocalDate checkOut() {
369	        return checkOut;
370	    }
371	
372	    public int guests() {
373	        return guests;
374	    }
375	
376	    public RatePlan ratePlan() {
377	        return ratePlan;
378	    }
379	
380	    public Price price() {
381	        return price;
382	    }
383	
384	    public ReservationStatus status() {
385	        return status;
386	    }
387	
388	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
389	    public BigDecimal amountPaid() {
390	        return amountPaid;
391	    }
392	
393	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
394	    public BigDecimal refund() {
395	        return refund;
396	    }
397	
398	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
399	    public boolean isPaid() {
400	        return status == ReservationStatus.CONFIRMED
401	                || status == ReservationStatus.CHECKED_IN
402	                || status == ReservationStatus.CHECKED_OUT;
403	    }
404	
405	    /** The money the inn keeps from this reservation. */
406	    public BigDecimal amountKept() {
407	        return refund == null ? amountPaid : amountPaid.subtract(refund);
408	    }
409	
410	    void changeStatus(ReservationStatus newStatus) {
411	        this.status = newStatus;
412	    }
413	
414	    void confirmPayment() {
415	        this.status = ReservationStatus.CONFIRMED;
416	        this.amountPaid = price.total();
417	    }
418	
419	    void cancel(BigDecimal refundAmount) {
420	        this.status = ReservationStatus.CANCELLED;
421	        this.refund = refundAmount;
422	    }
423	}

