382	    }
383	
384	    public ReservationStatus status() {
385	        return status;
386	    }
387	
388	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
389	    public BigDecimal amountPaid() {
390	        return amountPaid;
391	    }
392	
393	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
394	    public BigDecimal refund() {
395	        return refund;
396	    }
397	
398	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
399	    public boolean isPaid() {
400	        return status == ReservationStatus.CONFIRMED
401	                || status == ReservationStatus.CHECKED_IN
402	                || status == ReservationStatus.CHECKED_OUT;
403	    }
404	
405	    /** The money the inn keeps from this reservation. */
406	    public BigDecimal amountKept() {
407	        return refund == null ? amountPaid : amountPaid.subtract(refund);
408	    }
409	
410	    void changeStatus(ReservationStatus newStatus) {
411	        this.status = newStatus;
412	    }
413	
414	    void confirmPayment() {
415	        this.status = ReservationStatus.CONFIRMED;
416	        this.amountPaid = price.total();
417	    }
418	
